import math

def is_power_of_5(num):
    if num <= 0:
        return False
    if num == 1:
        return True
    while num % 5 == 0:
        num //= 5
    return num == 1

results = []
for n in range(3, 16):
    R = (2**n) - 3
    if is_power_of_5(R):
        # Calculate k such that R = 5^k
        k = round(math.log(R) / math.log(5))
        if 5**k == R:
             results.append((n, k))

print(results)

